draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // bird body
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 100, H/2 + Math.cos(t) * 50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // bird wings
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 100, H/2 + Math.cos(t) * 50 - 20);
  ctx.lineTo(W/2 + Math.sin(t) * 100 - Math.cos(t * 2) * 50, H/2 + Math.cos(t) * 50 + 20);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 100, H/2 + Math.cos(t) * 50 - 20);
  ctx.lineTo(W/2 + Math.sin(t) * 100 + Math.cos(t * 2) * 50, H/2 + Math.cos(t) * 50 + 20);
  ctx.stroke();

  // bird tail
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 100, H/2 + Math.cos(t) * 50 + 20);
  ctx.lineTo(W/2 + Math.sin(t) * 100, H/2 + Math.cos(t) * 50 + 50 + Math.sin(t * 2) * 20);
  ctx.stroke();

  ctx.restore();
}
